// src/pages/MainPage.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../components/Header';
import ButtonGrid from '../components/ButtonGrid';
import Notice from '../components/Notice';
import ExternalLinks from '../components/ExternalLinks';

export default function MainPage() {
  const [noticeText, setNoticeText] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    // TODO: 실제 서버에서 불러오실 때 fetch() 로 대체하세요
    setNoticeText(
    `ㅇ 토탈영업 직원 여러분 환영합니다! 
     - 계산하고자 하는 계산기를 위에 버튼에서 선택하세요.
     - 오류나 수정사항은 언제든지 연락주세요.
     - 추가 안내가 필요하시면 언제든 문의해주세요.
     - 2025.06.21일 현재 "결합" 계산기 미 구현 입니다.
     - 경고 문구를 주의 문구로 변경 및 출력 위치 변경
     - TV BIZ 계산기 입력 간소화 처리
     - 폴드7 출시에 따른 이벤트 특가 판매 모듈 구성
       ( 가격, 공시지원금 등은 차후 업데이트 예정)
     - 모바일 계산기 카테고리, 요금제, 데이터 용량 순으로 구성 변경   
     
` );
  }, []);

  const handleSelect = (label) => {
    switch (label) {
        case '삼성 폴드7 등 특가 판매':
        navigate('/event_offer');
        break;
      case '하이오더':
        navigate('/hiorder');
        break;
      case 'TV-Biz':
        navigate('/tvbiz');
        break;
      case '인터넷':
        navigate('/internet');
        break;
      case 'TV':
        navigate('/tvm');
        break;
      case '모바일':
        navigate('/mobile');
        break;
      case '결합':
        navigate('/bundle');
        break;
      case '주요 링크 모음':
        navigate('/ExternalLinks');
        break;  
      default:
        break;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* 헤더 */}
      <Header />

      {/* 버튼 그리드 + 공지사항 */}
      <main className="container mx-auto px-4 py-6">
        <ButtonGrid onSelect={handleSelect} />
        <Notice text={noticeText} />
      </main>
    </div>
  );
}
