/*
 * File: src/components/ExternalLinks.jsx
 * Description: Modular React component to render a list of external links.
 * Supports responsive layout on PC, mobile (Android, tablet), and prepared for iOS expansion.
 * Includes a "메인 메뉴로 돌아가기" button for navigation back to home, positioned at top-right.
 * Uses lucide-react for copy icon on each link card.
 */

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Copy } from 'lucide-react';
import { externalLinks } from '../config/externalLinksConfig';

export default function ExternalLinks() {
  const navigate = useNavigate();

  const copyToClipboard = async (url) => {
    try {
      await navigator.clipboard.writeText(url);
      window.alert('링크가 복사되었습니다!');
    } catch (err) {
      window.alert('복사에 실패했습니다.');
    }
  };

  return (
    <section className="pt-12 sm:pt-4 p-4 relative">
      {/* 메인 메뉴로 가기 버튼 */}
      <div className="absolute top-4 right-4">
        <button
          onClick={() => navigate('/')}
          className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 transition"
        >
          메인 메뉴로 돌아가기
        </button>
      </div>

      {/* 제목 */}
      <h2 className="text-xl font-bold mb-4 text-center">주요 링크 모음</h2>

      {/* 링크 목록: 반응형 그리드 */}
      <ul className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {externalLinks.map((link, idx) => (
          <li key={idx} className="relative">
            {/* 링크 카드 */}
            <a
              href={link.url}
              target="_blank"
              rel="noopener noreferrer"
              className="block text-center p-4 rounded-lg shadow hover:shadow-lg transition-shadow h-full"
            >
              <span className="text-base font-medium text-blue-600 underline">
                {link.name}
              </span>
            </a>
            {/* 복사 버튼: lucide-react 아이콘 */}
            <button
              onClick={() => copyToClipboard(link.url)}
              className="absolute top-2 right-2 p-1 bg-white rounded hover:bg-gray-100 transition-shadow shadow-sm"
              aria-label={`${link.name} 링크 복사`}
            >
              <Copy size={16} />
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

/*
 * Notes:
 * - lucide-react의 Copy 아이콘을 사용하여 복사 버튼을 표시합니다.
 * - navigator.clipboard API로 URL 복사 및 alert 처리.
 * - 상단 버튼은 useNavigate 훅으로 네비게이션 처리.
 * - Tailwind 반응형 그리드 및 텍스트 중앙 정렬 유지.
 */
